DO $$
DECLARE actor uuid; org bigint; un bigint; oc bigint; pt bigint; prod bigint; legacy_product bigint; form_a bigint; form_b bigint; form_c bigint;
 result jsonb; cmd uuid; legacy_cmd uuid; expired_cmd uuid; payload jsonb;
BEGIN
 PERFORM public.create_user_for_test('ticketing-delete','ticketing-delete@example.invalid');actor:=public.get_user_id('ticketing-delete');
 INSERT INTO public.organizations(title) VALUES('Ticketing delete') RETURNING id INTO org;
 UPDATE public.user_info SET organization=org WHERE id=actor;
 INSERT INTO public.units(title,organization) VALUES('Ticketing delete',org) RETURNING id INTO un;
 INSERT INTO public.unit_users(unit,"user",is_editor,is_manager) VALUES(un,actor,true,true);
 INSERT INTO public.occasions(title,organization,unit,link,start_time,end_time) VALUES('Ticketing delete',org,un,gen_random_uuid()::text,now(),now()+interval '1 day') RETURNING id INTO oc;
 INSERT INTO public.occasion_users(occasion,"user",is_editor,is_editor_view,is_editor_order,is_editor_order_view) VALUES(oc,actor,true,true,true,true);
 INSERT INTO eshop.product_types(occasion,title,type) VALUES(oc,'Products','spot') RETURNING id INTO pt;
 INSERT INTO eshop.products(occasion,title,product_type,price,currency_code) VALUES(oc,'Delete me',pt,10,'CZK') RETURNING id INTO prod;
 INSERT INTO eshop.products(occasion,title,product_type,price,currency_code) VALUES(oc,'Legacy delete',pt,10,'CZK') RETURNING id INTO legacy_product;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 ASSERT public.update_product_client_sync_v1(jsonb_build_object('id',prod,'title','Changed','expected_aggregate_version',0),gen_random_uuid())->>'status'='applied';
 BEGIN PERFORM public.delete_product_client_sync_v1(prod,gen_random_uuid(),NULL);RAISE EXCEPTION 'modern deletion accepted no version';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 ASSERT public.delete_product_client_sync_v1(prod,gen_random_uuid(),0)->>'status'='conflict';
 cmd:=gen_random_uuid();result:=public.delete_product_client_sync_v1(prod,cmd,1);ASSERT result->>'status'='applied';ASSERT public.delete_product_client_sync_v1(prod,cmd,1)=result;
 legacy_cmd:=gen_random_uuid();result:=public.delete_product_client_sync_v1(legacy_product,legacy_cmd);ASSERT result->>'status'='applied';ASSERT public.delete_product_client_sync_v1(legacy_product,legacy_cmd)=result;
 EXECUTE 'RESET ROLE';
 ASSERT NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=prod);
 ASSERT (SELECT request_sha256=encode(extensions.digest(convert_to(jsonb_build_object('productId',legacy_product)::text,'UTF8'),'sha256'),'hex') FROM public.client_mutation_receipts WHERE command_id=legacy_cmd),'legacy request hash stays compatible';
 UPDATE public.client_mutation_receipts SET status='expired',response=NULL,expired_at=clock_timestamp() WHERE command_id=cmd;
 ASSERT public.delete_product_client_sync_v1(prod,cmd,1)->>'code'='410';
 INSERT INTO public.forms(occasion,title,link) VALUES(oc,'A',gen_random_uuid()::text) RETURNING id INTO form_a;
 INSERT INTO public.forms(occasion,title,link) VALUES(oc,'B',gen_random_uuid()::text) RETURNING id INTO form_b;
 INSERT INTO public.form_fields(form,title,type,product_type) VALUES(form_a,'Shared','product_type',pt),(form_b,'Shared','product_type',pt);
 EXECUTE 'SET LOCAL ROLE authenticated';
 ASSERT public.update_form_client_sync_v1(jsonb_build_object('id',form_a,'occasion',oc,'title','Changed A','expected_aggregate_version',0),gen_random_uuid())->>'status'='applied';
 ASSERT public.delete_form_client_sync_v1(form_a,gen_random_uuid(),0)->>'status'='conflict';
 cmd:=gen_random_uuid();result:=public.delete_form_client_sync_v1(form_a,cmd,1);ASSERT result->>'status'='applied';ASSERT public.delete_form_client_sync_v1(form_a,cmd,1)=result;
 EXECUTE 'RESET ROLE';
 ASSERT EXISTS(SELECT 1 FROM eshop.product_types WHERE id=pt),'another form keeps the shared empty product type';
 legacy_cmd:=gen_random_uuid();result:=public.delete_form_client_sync_v1(form_b,legacy_cmd);ASSERT result->>'status'='applied';ASSERT public.delete_form_client_sync_v1(form_b,legacy_cmd)=result;
 UPDATE public.client_mutation_receipts SET status='expired',response=NULL,expired_at=clock_timestamp() WHERE command_id=cmd;
 ASSERT public.delete_form_client_sync_v1(form_a,cmd,1)->>'code'='410';
 INSERT INTO public.forms(occasion,title,link) VALUES(oc,'Attach blueprint',gen_random_uuid()::text) RETURNING id INTO form_c;
 payload:=jsonb_build_object('id',oc,'title','Ticketing delete','organization',org,'unit',un,'features','[{"code":"blueprint","is_enabled":true}]'::jsonb);
 ASSERT public.save_occasion_client_sync_v1(oc,gen_random_uuid(),0,payload)->>'status'='applied';
 ASSERT (SELECT blueprint IS NOT NULL FROM public.forms WHERE id=form_c);
 ASSERT public.update_form_client_sync_v1(jsonb_build_object('id',form_c,'occasion',oc,'expected_aggregate_version',0),gen_random_uuid())->>'status'='conflict','occasion feature attachment invalidates the original form draft';
 ASSERT NOT has_table_privilege('authenticated','public.forms','UPDATE');
 ASSERT NOT has_table_privilege('authenticated','eshop.spots','UPDATE');
 ASSERT NOT has_function_privilege('service_role','public.update_product_internal_v1(jsonb)','EXECUTE');
END $$;
